mapper.select:
SELECT chunk_index AS chunkIndex, content
FROM document_chunk
WHERE doc_id = #{docId}
  AND version = #{version}
ORDER BY chunk_index ASC

SELECT chunk_index AS chunkIndex, content
FROM document_chunk
WHERE doc_id = #{docId}
  AND version = #{version}
ORDER BY chunk_index ASC
LIMIT #{limit} OFFSET #{offset}

sql.if:
AND metadata->>'periodYear' = #{temporalOverlap.periodYear}
AND (
    (metadata->>'periodStart' IS NOT NULL AND metadata->>'periodStart' <> ''
     AND metadata->>'periodEnd' IS NOT NULL AND metadata->>'periodEnd' <> ''
     AND metadata->>'periodStart' <= #{temporalOverlap.rangeEnd}
     AND metadata->>'periodEnd' >= #{temporalOverlap.rangeStart})

        OR (

            CONCAT(',', COALESCE(metadata->>'periodMonths',''), ',') LIKE CONCAT('%,', #{m}, ',%')

        )

)

mapper.select:
SELECT ,
       COALESCE(1 - (embedding <=> #{embedding,typeHandler=com.knowbase.vector.mybatis.PGvectorTypeHandler}), 0) AS score
FROM document_chunk
WHERE library_id = #{libraryId}
  AND tenant_id = #{tenantId}
  AND embedding IS NOT NULL

    AND doc_id IN

        #{id}






                AND metadata->>#{clause.field} >= #{clause.value}


                AND metadata->>#{clause.field} <= #{clause.value}


                AND metadata->>#{clause.field} = #{clause.value}






    AND metadata->>'chunkProfileId' IN

        #{profileId}


ORDER BY embedding <=> #{embedding,typeHandler=com.knowbase.vector.mybatis.PGvectorTypeHandler},
         chunk_id ASC
LIMIT #{topK}

SELECT ,
       COALESCE(ts_rank_cd(to_tsvector('simple', content), plainto_tsquery('simple', #{query})), 0) AS score
FROM document_chunk
WHERE library_id = #{libraryId}
  AND tenant_id = #{tenantId}
  AND to_tsvector('simple', content) @@ plainto_tsquery('simple', #{query})

    AND doc_id IN

        #{id}






                AND metadata->>#{clause.field} >= #{clause.value}


                AND metadata->>#{clause.field} <= #{clause.value}


                AND metadata->>#{clause.field} = #{clause.value}






    AND metadata->>'chunkProfileId' IN

        #{profileId}


ORDER BY score DESC, chunk_id ASC
LIMIT #{topK}

mapper.update:
UPDATE document_chunk
SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('chunkProfileId', #{chunkProfileId})
WHERE doc_id = #{docId}
  AND version = #{version}

UPDATE document_chunk
SET metadata = #{metadataJson}::jsonb
WHERE chunk_id = #{chunkId}

mapper.select:
SELECT DISTINCT metadata->>'chunkProfileId'
FROM document_chunk
WHERE library_id = #{libraryId}
  AND tenant_id = #{tenantId}
  AND metadata->>'chunkProfileId' IS NOT NULL
  AND metadata->>'chunkProfileId' <> ''

mapper.delete:
DELETE FROM document_chunk c
WHERE c.library_id = #{libraryId}
  AND c.tenant_id = #{tenantId}
  AND c.metadata->>'chunkProfileId' = #{chunkProfileId}
  AND NOT EXISTS (
      SELECT 1 FROM doc_metadata d
      WHERE d.library_id = c.library_id
        AND d.deleted = false
        AND d.chunk_profile_id = #{chunkProfileId}
  )
